//! Probe the real matcher with pipe-delimited reference grids generated by the audit.
//! Each line is: reference_index|nine comma-separated item IDs (0 = empty).
use mc4d_core::{crafting, item::Stack};
fn main() {
    let path=std::env::args().nth(1).expect("reference grid file");
    let text=std::fs::read_to_string(path).expect("read reference grid file");
    for line in text.lines() {
        let (index,ids)=line.split_once('|').expect("index|grid");
        let grid:Vec<_>=ids.split(',').map(|id|id.parse::<mc4d_core::item::ItemId>().unwrap()).map(|id|(id!=0).then(||Stack::new(id,1))).collect();
        match crafting::recipe(&grid,3) {
            Some(found)=>println!("{index}|{}|{}",found.output.block,found.output.count),
            None=>println!("{index}|none"),
        }
    }
}
